// The Benin Life logo: the Ada (state sword of authority, left) and the Eben (Ugie dance sword,
// right) with a coral bead and strand between them. Inline SVG so it stays crisp and themeable.
// Geometry is generated by scripts/brand/build_brand.py (src/ui/logoArt.ts). See docs/BRAND.md.
import { useId } from 'react';
import { LOGO_DEFS, LOGO_FULL, LOGO_MARK, LOGO_MARKPLAIN, LOGO_MARKSMALL, LOGO_STACKED } from './logoArt';

export type LogoVariant = 'full' | 'stacked' | 'mark';

export interface LogoProps {
  variant?: LogoVariant;
  /** Height in px for full/stacked; width = height for mark. */
  size?: number;
  /** mark only: false drops the warm-black tile (swords + bead on their own). */
  tile?: boolean;
  /** Wordmark colours. 'auto' follows currentColor; 'light' = ink on light; 'dark' = ivory on dark. */
  tone?: 'auto' | 'light' | 'dark';
  className?: string;
  /** Accessible name. Pass '' when a visible "Benin Life" label sits next to the mark. */
  title?: string;
}

const TONES = {
  auto: undefined,
  light: { ['--logo-ink' as string]: '#1E1410', ['--logo-accent' as string]: '#C0392B' },
  dark: { ['--logo-ink' as string]: '#F7EBD3', ['--logo-accent' as string]: '#E8664F' },
} as const;

export function Logo({ variant = 'mark', size = 40, tile = true, tone = 'auto', className, title = 'Benin Life' }: LogoProps) {
  const id = `bl${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  // Below 40px the detailed mark turns to mush, so the tile uses the simplified favicon drawing.
  const art = variant === 'full' ? LOGO_FULL
    : variant === 'stacked' ? LOGO_STACKED
    : !tile ? LOGO_MARKPLAIN
    : size < 40 ? LOGO_MARKSMALL : LOGO_MARK;
  const [, , vw, vh] = art.viewBox.split(' ').map(Number);
  const height = size;
  const width = variant === 'mark' ? size : Math.round((size * vw) / vh);
  const html = `<defs>${LOGO_DEFS}</defs>${art.body}`.replaceAll('__ID__', id);
  return (
    <svg
      className={['bl-logo', className].filter(Boolean).join(' ')}
      viewBox={art.viewBox}
      width={width}
      height={height}
      style={TONES[tone]}
      role={title ? 'img' : undefined}
      aria-label={title || undefined}
      aria-hidden={title ? undefined : true}
      focusable="false"
      // Static, build-time generated markup (no user input).
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
